import { z } from "zod"

// Base schema from JSON Schema (generated by json-schema-to-zod)
// This is the raw output from codegen - we enhance it below
const BaseProjectSchema = z.object({ 
  "id": z.number().int().describe("Unique project identifier").optional(), 
  "name": z.string().describe("Project name"), 
  "description": z.union([z.string().describe("Project description"), z.null().describe("Project description")]).describe("Project description").optional(), 
  "userId": z.union([z.number().int().describe("ID of the user who owns this project"), z.null().describe("ID of the user who owns this project")]).describe("ID of the user who owns this project").optional(), 
  "createdAt": z.string().datetime({ offset: true }).describe("Timestamp when project was created").optional(), 
  "updatedAt": z.union([z.string().datetime({ offset: true }).describe("Timestamp when project was last updated"), z.null().describe("Timestamp when project was last updated")]).describe("Timestamp when project was last updated").optional() 
}).describe("A project containing multiple FCM models");

// Enhanced schemas with proper date handling for API
export const ProjectSchema = BaseProjectSchema.extend({
  createdAt: z.string().or(z.date()).optional(),
  updatedAt: z.string().or(z.date()).nullable().optional(),
});

export const ProjectStorageSchema = z.object({
  id: z.number(),
  name: z.string(),
  description: z.string().nullable(),
  createdAt: z.date(),
  updatedAt: z.date().nullable(),
  userId: z.number().nullable()
});

export type Project = z.infer<typeof ProjectSchema>;
export type ProjectStorage = z.infer<typeof ProjectStorageSchema>;

// Keep default export for codegen compatibility (will be overwritten on next codegen)
export default BaseProjectSchema;
